#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
using namespace std;

int removeElement(vector<int>& nums, int val) {
    int k = 0;
    for (int i = 0; i < nums.size(); i++) {
        if (nums[i] != val) {
            nums[k] = nums[i];
            k++;
        }
    }
    return k;
}

int main() {
    string line, valStr;
    if (getline(cin, line) && getline(cin, valStr)) {
        if (line.front() == '[') line = line.substr(1, line.size() - 2);
        stringstream ss(line);
        vector<int> nums;
        string v;
        while (getline(ss, v, ',')) {
            nums.push_back(stoi(v));
        }
        cout << removeElement(nums, stoi(valStr)) << endl;
    }
    return 0;
}

