#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int removeElement(int* nums, int numsSize, int val) {
    int k = 0;
    for (int i = 0; i < numsSize; i++) {
        if (nums[i] != val) {
            nums[k] = nums[i];
            k++;
        }
    }
    return k;
}

int main() {
    char buffer[1000];
    if (fgets(buffer, sizeof(buffer), stdin)) {
        char* p = buffer;
        while (*p && (*p == '[' || *p == ' ' || *p == '\n')) p++;
        int nums[100], n = 0;
        char* token = strtok(p, ",] \n");
        while (token) {
            nums[n++] = atoi(token);
            token = strtok(NULL, ",] \n");
        }
        if (fgets(buffer, sizeof(buffer), stdin)) {
            int val = atoi(buffer);
            printf("%d\n", removeElement(nums, n, val));
        }
    }
    return 0;
}
